import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Stars } from '@react-three/drei';
import * as THREE from 'three';

// 程序化生成行星纹理
function createPlanetTexture(baseColor, detail = 1) {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');

  // 基础颜色
  const r = parseInt(baseColor.slice(1, 3), 16);
  const g = parseInt(baseColor.slice(3, 5), 16);
  const b = parseInt(baseColor.slice(5, 7), 16);

  ctx.fillStyle = baseColor;
  ctx.fillRect(0, 0, 512, 256);

  // 添加噪点细节
  for (let i = 0; i < 2000 * detail; i++) {
    const x = Math.random() * 512;
    const y = Math.random() * 256;
    const size = Math.random() * 8 + 2;
    const variation = (Math.random() - 0.5) * 40;

    ctx.fillStyle = `rgba(${r + variation}, ${g + variation}, ${b + variation}, ${Math.random() * 0.3})`;
    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.fill();
  }

  // 添加条纹（对于气态行星）
  if (detail > 1) {
    for (let i = 0; i < 15; i++) {
      const y = Math.random() * 256;
      const height = Math.random() * 20 + 5;
      const variation = (Math.random() - 0.5) * 60;

      ctx.fillStyle = `rgba(${r + variation}, ${g + variation}, ${b + variation}, ${Math.random() * 0.4 + 0.1})`;
      ctx.fillRect(0, y, 512, height);
    }
  }

  return new THREE.CanvasTexture(canvas);
}

// 真实行星数据：名称、相对距离(AU)、相对半径(相对于地球)、颜色、公转速度、自转速度
const planetData = [
  { name: '水星', distance: 0.39, radius: 0.38, color: '#A5A5A5', orbitSpeed: 4.15, rotSpeed: 0.004, detail: 1 },
  { name: '金星', distance: 0.72, radius: 0.95, color: '#E5C36B', orbitSpeed: 1.62, rotSpeed: 0.003, detail: 1 },
  { name: '地球', distance: 1.0, radius: 1.0, color: '#4B9CD3', orbitSpeed: 1.0, rotSpeed: 0.02, detail: 2 },
  { name: '火星', distance: 1.52, radius: 0.53, color: '#C16051', orbitSpeed: 0.53, rotSpeed: 0.019, detail: 1 },
  { name: '木星', distance: 5.2, radius: 11.2, color: '#C6842F', orbitSpeed: 0.18, rotSpeed: 0.04, detail: 3 },
  { name: '土星', distance: 9.54, radius: 9.4, color: '#E8C554', orbitSpeed: 0.12, rotSpeed: 0.045, hasRing: true, detail: 3 },
  { name: '天王星', distance: 19.2, radius: 4.0, color: '#7B8BAA', orbitSpeed: 0.06, rotSpeed: 0.03, detail: 2 },
  { name: '海王星', distance: 30.1, radius: 3.9, color: '#3D58DB', orbitSpeed: 0.04, rotSpeed: 0.032, detail: 2 },
];

function Sun() {
  const meshRef = useRef();

  useFrame(() => {
    meshRef.current.rotation.y += 0.002;
  });

  return (
    <group>
      <mesh ref={meshRef}>
        <sphereGeometry args={[3, 64, 64]} />
        <meshStandardMaterial
          emissive={new THREE.Color('#FFD700')}
          emissiveIntensity={2}
          color={new THREE.Color('#FF6600')}
          toneMapped={false}
        />
      </mesh>
      <pointLight intensity={2} distance={50} />
    </group>
  );
}

function OrbitLine({ distance }) {
  const radius = distance;
  const segments = 128;
  const positions = [];
  for (let i = 0; i <= segments; i++) {
    const angle = (i / segments) * Math.PI * 2;
    positions.push(Math.cos(angle) * radius, 0, Math.sin(angle) * radius);
  }
  const geometry = useMemo(() => {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    return geo;
  }, []);

  return (
    <mesh geometry={geometry}>
      <meshBasicMaterial color="#333333" transparent opacity={0.3} />
    </mesh>
  );
}

function Planet({ data }) {
  const meshRef = useRef();
  const groupRef = useRef();
  const [hovered, setHovered] = useState(false);

  // 创建程序化纹理
  const texture = useMemo(() => {
    return createPlanetTexture(data.color, data.detail);
  }, [data.color, data.detail]);

  useFrame(() => {
    const time = Date.now() * 0.001;
    const angle = time * data.orbitSpeed;
    groupRef.current.position.x = Math.cos(angle) * data.distance;
    groupRef.current.position.z = Math.sin(angle) * data.distance;
    meshRef.current.rotation.y += data.rotSpeed;
  });

  return (
    <group ref={groupRef}>
      <mesh
        ref={meshRef}
        onPointerOver={() => setHovered(true)}
        onPointerOut={() => setHovered(false)}
      >
        <sphereGeometry args={[data.radius, 64, 64]} />
        <meshStandardMaterial
          map={texture}
          emissive={hovered ? new THREE.Color(data.color).multiplyScalar(0.3) : new THREE.Color('#000000')}
          emissiveIntensity={hovered ? 0.5 : 0}
        />
      </mesh>
      {data.hasRing && (
        <mesh rotation={[0.4, 0, 0]}>
          <ringGeometry args={[data.radius * 1.4, data.radius * 2.2, 64]} />
          <meshStandardMaterial color="#C0A060" transparent opacity={0.7} side={THREE.DoubleSide} />
        </mesh>
      )}
    </group>
  );
}

function App() {
  return (
    <div style={{ width: '100vw', height: '100vh' }}>
      <Canvas camera={{ position: [0, 20, 30], fov: 50 }}>
        <color attach="background" args={['#050510']} />
        <ambientLight intensity={0.1} />
        <OrbitControls makeDefault />
        <Stars radius={100} depth={50} count={5000} scale={1} density={5} color={0x606060} />
        <Sun />
        {planetData.map((planet, index) => (
          <React.Fragment key={index}>
            <OrbitLine distance={planet.distance} />
            <Planet data={planet} />
          </React.Fragment>
        ))}
      </Canvas>
      <div style={{
        position: 'fixed',
        top: '10px',
        left: '10px',
        color: '#FFFFFF',
        fontFamily: 'monospace',
        fontSize: '14px',
        zIndex: 1000,
        pointerEvents: 'none',
        background: 'rgba(0,0,0,0.5)',
        padding: '10px',
        borderRadius: '5px'
      }}>
        <div>太阳系模拟</div>
        <div style={{ fontSize: '12px', marginTop: '5px', opacity: 0.7 }}>
          鼠标左键旋转 · 右键平移 · 滚轮缩放
        </div>
      </div>
    </div>
  );
}

export default App;
